import subprocess
import sys
import unittest

from slugify import slugify


class OracleTests(unittest.TestCase):
    def test_accents(self):
        self.assertEqual(slugify("Crème brûlée & Coffee!"), "creme-brulee-coffee")

    def test_separator_runs(self):
        self.assertEqual(slugify("alpha___beta...gamma"), "alpha-beta-gamma")

    def test_edges_and_digits(self):
        self.assertEqual(slugify("---Version 2.0---"), "version-2-0")

    def test_empty(self):
        self.assertEqual(slugify("!!!"), "")

    def test_cli(self):
        result = subprocess.run(
            [sys.executable, "slugify.py", "  Déjà vu  "],
            check=True,
            capture_output=True,
            text=True,
        )
        self.assertEqual(result.stdout, "deja-vu\n")


if __name__ == "__main__":
    unittest.main()
